<script setup>import AdminNavigation from '@/Components/Admin/AdminNavigation.vue';import PortalLayout from '@/Layouts/PortalLayout.vue';import{Head,Link,router}from'@inertiajs/vue3';const props=defineProps({tickets:Array,filters:Object,products:Array,agents:Array,counts:Object});const form={...props.filters};let timer;const apply=()=>{clearTimeout(timer);timer=setTimeout(()=>router.get(route('admin.support.index'),form,{preserveState:true,replace:true}),250)};</script>
<template><Head title="Support management"/><PortalLayout area="Administration"><template #navigation><AdminNavigation active="support"/></template><h1 class="text-3xl font-bold">Support management</h1><p class="mt-2 text-slate-600">Customer issues, SLA performance and team workload.</p><div class="my-6 grid gap-4 sm:grid-cols-2 xl:grid-cols-5"><div v-for="(value,key) in counts" :key="key" class="rounded-xl bg-white p-4 shadow-sm"><p class="text-xs uppercase text-slate-500">{{ key.replace('_',' ') }}</p><p class="text-2xl font-bold">{{ value }}</p></div></div><div class="mb-5 grid gap-3 rounded-2xl bg-white p-4 shadow-sm md:grid-cols-3 xl:grid-cols-6"><input v-model="form.search" placeholder="Search" @input="apply"/><select v-model="form.status" @change="apply"><option value="">All statuses</option><option v-for="v in ['open','in_progress','waiting_customer','resolved','closed']" :key="v">{{ v }}</option></select><select v-model="form.priority" @change="apply"><option value="">All priorities</option><option v-for="v in ['low','normal','high','urgent']" :key="v">{{ v }}</option></select><select v-model="form.category" @change="apply"><option value="">All categories</option><option v-for="v in ['technical','billing','license','deployment','training','general']" :key="v">{{ v }}</option></select><select v-model="form.product" @change="apply"><option value="">All products</option><option v-for="p in products" :key="p.uuid" :value="p.uuid">{{ p.name }}</option></select><select v-model="form.assigned_to" @change="apply"><option value="">Any agent</option><option v-for="a in agents" :key="a.id" :value="a.id">{{ a.name }}</option></select></div><div class="overflow-hidden rounded-2xl bg-white shadow-sm"><p v-if="!tickets.length" class="p-8 text-center text-slate-500">No matching tickets.</p><Link v-for="ticket in tickets" :key="ticket.uuid" :href="route('admin.support.show',ticket.uuid)" class="grid gap-3 border-b p-5 hover:bg-slate-50 md:grid-cols-[1fr_180px_140px]"><div><strong class="text-[#0B3D6E]">{{ ticket.ticket_number }}</strong><p>{{ ticket.subject }}</p><small>{{ ticket.customer.name }} · {{ ticket.product?.name || 'General' }}</small></div><div><p class="text-sm">{{ ticket.assignee?.name || 'Unassigned' }}</p><small class="text-slate-500">{{ ticket.category }}</small></div><div class="text-right"><span class="text-xs font-bold uppercase">{{ ticket.status }}</span><p class="text-sm">{{ ticket.priority }}</p></div></Link></div></PortalLayout></template>
